using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Input;
using System.Windows.Media;
internal sealed partial class ModernWorkspace {
 Grid homeWidgetGrid;
 Border EditableHomeCard(HomeBlock block,UIElement body,Action more){
  var card=Card(HomeLayout.Name(block.id),body,more);var old=(StackPanel)card.Child;var heading=old.Children[0];if(block.id=="priorities"||block.id=="resume")foreach(var button in ((DockPanel)heading).Children.OfType<Button>())button.Content=block.id=="priorities"?"Choisir":"Reprendre";old.Children.Clear();
  var layout=new Grid();layout.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});layout.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});
  var bar=new DockPanel();if(homeEditing){var handle=new Border{Width=24,Background=Brushes.Transparent,Cursor=Cursors.SizeAll,Margin=new Thickness(0,0,7,0),ToolTip="Glisser pour déplacer ce bloc",Child=T("⠿",18,Muted)};Point? start=null;handle.MouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){start=e.GetPosition(handle);};handle.MouseMove+=delegate(object sender,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed||!start.HasValue)return;var point=e.GetPosition(handle);if(Math.Abs(point.X-start.Value.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(point.Y-start.Value.Y)<SystemParameters.MinimumVerticalDragDistance)return;start=null;DragDrop.DoDragDrop(handle,new DataObject("MonEspace.HomeBlock",block.id),DragDropEffects.Move);};DockPanel.SetDock(handle,Dock.Left);bar.Children.Add(handle);var options=Btn("···",delegate{HomeBlockMenu(block);},false,true);options.ToolTip="Largeur, hauteur et visibilité";DockPanel.SetDock(options,Dock.Right);bar.Children.Add(options);}bar.Children.Add(heading);layout.Children.Add(bar);
  int height=block.height>0?block.height:block.size=="Grand"?540:0;var viewport=new ScrollViewer{Content=body,VerticalScrollBarVisibility=height>0?ScrollBarVisibility.Auto:ScrollBarVisibility.Disabled,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(viewport,1);layout.Children.Add(viewport);card.Child=layout;if(height>0)card.Height=height;
  card.AllowDrop=homeEditing;card.DragOver+=delegate(object sender,DragEventArgs e){if(!e.Data.GetDataPresent("MonEspace.HomeBlock"))return;e.Effects=DragDropEffects.Move;e.Handled=true;};card.Drop+=delegate(object sender,DragEventArgs e){if(!homeEditing||!e.Data.GetDataPresent("MonEspace.HomeBlock"))return;string source=Convert.ToString(e.Data.GetData("MonEspace.HomeBlock"));var at=e.GetPosition(homeWidgetGrid);int column=(Keyboard.Modifiers&ModifierKeys.Control)!=0?2:at.X<homeWidgetGrid.ActualWidth/2?0:1;ChangeDay(delegate{DayDashboard.Move(store.Value,source,block.id,column);});e.Handled=true;};
  if(homeEditing){double horizontal=0;var thumb=new Thumb{Width=20,Height=20,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Bottom,Cursor=Cursors.SizeNWSE,Margin=new Thickness(0,0,-12,-12),ToolTip="Hauteur libre · glisser largement à droite pour toute la largeur"};thumb.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><Border Background='Transparent'><TextBlock Text='◢' FontSize='15' Foreground='#B49D7A'/></Border></ControlTemplate>");Grid.SetRow(thumb,1);layout.Children.Add(thumb);thumb.DragStarted+=delegate{horizontal=0;if(Double.IsNaN(card.Height))card.Height=Math.Max(180,card.ActualHeight);viewport.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;};thumb.DragDelta+=delegate(object sender,DragDeltaEventArgs e){horizontal+=e.HorizontalChange;card.Height=Math.Max(180,Math.Min(900,card.Height+e.VerticalChange));};thumb.DragCompleted+=delegate(object sender,DragCompletedEventArgs e){if(e.Canceled){Refresh();return;}int finalHeight=(int)Math.Round(card.Height);ChangeDay(delegate{block.height=finalHeight;if(horizontal>100)block.column=2;else if(horizontal< -100&&block.column==2)block.column=0;DayDashboard.RememberLayout(store.Value);});};}
  return card;
 }
 void HomeBlockMenu(HomeBlock block){
  var menu=new ContextMenu();Action<string,Action> add=delegate(string title,Action action){var item=new MenuItem{Header=title};item.Click+=delegate{ChangeDay(delegate{action();DayDashboard.RememberLayout(store.Value);});};menu.Items.Add(item);};
  add("Colonne gauche",delegate{block.column=0;});add("Colonne droite",delegate{block.column=1;});add("Toute la largeur",delegate{block.column=2;});menu.Items.Add(new Separator());add("Hauteur automatique",delegate{block.height=0;block.size="Normal";});add("Compact",delegate{block.height=240;block.size="Compact";});add("Normal",delegate{block.height=400;block.size="Normal";});add("Grand",delegate{block.height=620;block.size="Grand";});menu.Items.Add(new Separator());add("Masquer ce bloc",delegate{block.visible=false;});menu.IsOpen=true;
 }
}
